/* Icones do menu, guardados como imagem embutida em texto.
   Moram aqui fora porque nunca mudam: o aparelho baixa uma vez
   e reaproveita em toda atualizacao do app. */
var NAVIC={home:"<img src=\"data:image/png;base64,\" alt=\"Início\">",cal:"<img src=\"data:image/png;base64,\" alt=\"Agenda\">",ball:"<img src=\"data:image/png;base64,\" alt=\"Alunos\">",clip:"<img src=\"data:image/png;base64,\" alt=\"Avaliações\">",cash:"<img src=\"data:image/png;base64,\" alt=\"Caixa\">",bars:"<img src=\"data:image/png;base64,\" alt=\"Financeiro\">",line:"<img src=\"data:image/png;base64,\" alt=\"Gráficos\">",trophy:"<img src=\"data:image/png;base64,\" alt=\"Torneio\">"};
function pintarIcones(){var m=document.querySelectorAll(".ico[data-ic]");for(var i=0;i<m.length;i++){if(!m[i].innerHTML)m[i].innerHTML=NAVIC[m[i].getAttribute("data-ic")]||"";}}pintarIcones();/* pinta de novo quando o resto do HTML carregar, para nao depender da ordem dos blocos */document.addEventListener("DOMContentLoaded",pintarIcones);
